using Brutal.Numerics;

namespace KSArmory;

/// <summary>
/// Every weapon system the mod knows about.
///
/// <para><b>This is the file to add to.</b> A new launcher, round or sensor is an entry here
/// plus its art; no other C# needs to change. Discovery is by <see cref="LauncherProfile.PartId"/>,
/// so the system picks up whatever is fitted without anything hardcoding a particular
/// vehicle.</para>
///
/// <para>The geometry of the launchers <c>tools/model/pantsir.py</c> builds is generated by it and
/// checked against the exported mesh by <c>tools/validate-parts.py</c>. Rerun the model build and
/// paste what it prints rather than editing the numbers.</para>
/// </summary>
public static class Arsenal
{
    // ---- Munitions ------------------------------------------------------
    /// <summary>
    /// The same round integrating at a stated sub-step. What <see cref="IcbmConfig.WarheadSubStepMs"/> flies;
    /// a copy rather than an edit, because the registered profile is shared by every rocket in the world.
    /// </summary>
    internal static MunitionProfile RoundAtSubStep(MunitionProfile round, double seconds)
    {
        MunitionProfile stepped = round.Copy();
        stepped.SubStepSeconds = (float)seconds;
        return stepped;
    }

    // ---- Sensors --------------------------------------------------------
    // ---- Launchers ------------------------------------------------------
    // ---- Countermeasures -------------------------------------------------

    // ---- Registry -------------------------------------------------------

    public static readonly IReadOnlyList<LauncherProfile> Launchers =
        [];
    public static readonly IReadOnlyList<MunitionProfile> Munitions =
        [];
    public static readonly IReadOnlyList<SensorProfile> Sensors =
        [];

    /// <summary>
    /// Optical heads. Most are parts in their own right; one rides a launcher's turret, and
    /// nothing downstream can tell which is which — nor which gimbal any of them is hung on.
    /// </summary>
    public static readonly IReadOnlyList<OpticProfile> Optics =
        [];

    /// <summary>Parts that only search.</summary>
    public static readonly IReadOnlyList<SearchSetProfile> SearchSets = [];

    public static readonly IReadOnlyList<DecoyProfile> Decoys = [];
    public static readonly IReadOnlyList<DispenserProfile> Dispensers = [];

    /// <summary>
    /// The parts this mod recognises on a craft it did not design, keyed by part Id.
    ///
    /// <para>Separate from <see cref="Launchers"/>, which describes a whole weapon system as one
    /// prefab part with its geometry generated into this file. This describes *components*: what
    /// a player assembled, surveyed where they put it. A prefab appears in both, because the
    /// Pantsir is a launcher however it got onto the craft.</para>
    ///
    /// <para>The mechanism is what a new weapon system plugs into, and it is testable before any of
    /// that system's art exists.</para>
    /// </summary>
    public static readonly IReadOnlyList<ComponentProfile> Components =
    [
    ];

    /// <summary>
    /// The same lookup against an explicit registry.
    ///
    /// <para>Exists so the selection logic can be tested against a registry of any size. With one
    /// entry every registry assertion is trivially satisfied and cannot distinguish "picks the
    /// right one" from "picks the only one".</para>
    /// </summary>
    internal static LauncherProfile? LauncherForPart(IReadOnlyList<LauncherProfile> from, string? partId)
    {
        if (string.IsNullOrEmpty(partId)) return null;

        for (int i = 0; i < from.Count; i++)
        {
            if (from[i].PartId == partId) return from[i];
        }
        return null;
    }

    /// <summary>
    /// The round and sensor a launcher names, resolved together against explicit registries.
    ///
    /// <para>Together because a launcher left holding another system's round is a wrong-weapon
    /// bug with nothing on screen to show for it. Every caller that adopts a launcher takes all
    /// three, and this is the one place that pairing is made.</para>
    /// </summary>
    internal static (MunitionProfile Munition, SensorProfile Sensor) LoadoutFor(
        LauncherProfile launcher,
        IReadOnlyList<MunitionProfile> munitions,
        IReadOnlyList<SensorProfile> sensors)
        => (launcher.Munition.Length == 0 ? MunitionProfile.None : Named(munitions, launcher.Munition, m => m.Name),
            Named(sensors, launcher.Sensor, s => s.Name));

    /// <summary>
    /// First entry whose key matches, or the first entry as a fallback. Internal rather than
    /// private so the fallback can be tested against a registry with more than one candidate,
    /// where "matched" and "fell back to element zero" are actually distinguishable.
    ///
    /// <para>The fallback keeps a typo in a shipped profile playable and cannot report one.
    /// <see cref="Catalogue.TryMunitionNamed"/> is the form that can, and is what anything
    /// judging a name rather than flying a round asks.</para>
    /// </summary>
    internal static T Named<T>(IReadOnlyList<T> from, string name, Func<T, string> key)
    {
        for (int i = 0; i < from.Count; i++)
        {
            if (key(from[i]) == name) return from[i];
        }
        return from[0];
    }
}
